-- ============================================================
-- Lesson enhancements for "istqb-foundation-masterclass" Module 10.
-- Generated by scripts/content/build-module.mjs — do not hand-edit;
-- edit scripts/content/istqb-module10.mjs and regenerate. Run AFTER
-- lesson-enhancements-schema.sql and the lesson seeds. Idempotent.
